import { NVector3, NVectorUtility } from '../../../../../../lib/NJSCore';
import { PixelMapGlobe } from '../../../../../../lib/NJSCore/Core/NData';
import { GeometryCommon } from '../../GeometryCommon/GeometryCommon';
import { WallPaperBase } from '../Base/WallPaperBase';
import * as THREE from 'three';

import jsonLowGlobeLand from '../../../Asset/obj/lowEarth/lowGlobeLand.json';
import jsonLowGlobeSphere from '../../../Asset/obj/lowEarth/lowGlobeSphere.json';
import jsonLowGlobeCloud from '../../../Asset/obj/lowEarth/lowGlobeCloud.json';

export class GlobeLowPoly extends WallPaperBase {

    public landGeometry: THREE.BufferGeometry;
    public landMat: THREE.MeshPhongMaterial;
    public landMesh: THREE.Mesh;

    public sphereGeometry: THREE.BufferGeometry;
    public sphereMat: THREE.MeshPhongMaterial;
    public sphereMesh: THREE.Mesh;

    public envirGeometry: THREE.BufferGeometry;
    public envirMat: THREE.MeshPhongMaterial;
    public envirMesh: THREE.Mesh;

    public cloudGeo: THREE.BufferGeometry;
    public cloudMat: THREE.MeshPhongMaterial;
    public cloudMeshGroup: THREE.Group;

    public pixelMapGlobe: PixelMapGlobe;
    public vec: NVector3;
    public radius: number = 1;
    public xSeg: number = 360;
    public ySeg: number = 180;

    public t: number = 0.0;
    public isDone: boolean = false;

    public meshSpot: THREE.Mesh[] = [];
    public scene: THREE.Scene;

    public mapNight: HTMLImageElement;
    public mapDay: HTMLImageElement;
    public numBaseMapShfit: number = 0;

    constructor(scene: THREE.Scene, x: number = 0, y: number = 0, z: number = 0, radius: number = 0.1, xSeg: number = 36, ySeg: number = 18) {
        super();
        this.scene = scene;
        this.vec = new NVector3(x, y, z);

        this.xSeg = xSeg;
        this.ySeg = ySeg;
        this.radius = radius;

        this.initGlobe();
        this.initCloud();
        this.initEnvironment();
    }

    private initGlobe(): void {
        this.landGeometry = new THREE.BufferGeometry();
        this.landMat = new THREE.MeshPhongMaterial({ color: 0xaac456, flatShading: true, shininess: 10, emissive: 0x222222 });
        this.landMesh = this.getMeshFromJson(this.landGeometry, this.landMat, jsonLowGlobeLand);
        this.scene.add(this.landMesh);
        GeometryCommon.listMesh.push(this.landMesh);

        this.sphereGeometry = new THREE.BufferGeometry();
        this.sphereMat = new THREE.MeshPhongMaterial({ color: 0xabd9ec, flatShading: true, shininess: 30, emissive: 0x222222 });
        this.sphereMesh = this.getMeshFromJson(this.sphereGeometry, this.sphereMat, jsonLowGlobeSphere);
        this.scene.add(this.sphereMesh);
        GeometryCommon.listMesh.push(this.sphereMesh);
    }

    private getMeshFromJson(geo: THREE.BufferGeometry, mat: THREE.MeshPhongMaterial, json: any): THREE.Mesh {
        const vertices = new Float32Array(json.v.flat());
        const indices = new Uint16Array(json.f.flat());
        const colors = new Float32Array(json.vc.flat());

        geo.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
        geo.setIndex(new THREE.BufferAttribute(indices, 1));
        geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        geo.applyMatrix4(new THREE.Matrix4().makeRotationX(- Math.PI / 2));
        geo.applyMatrix4(new THREE.Matrix4().makeScale(this.radius, this.radius, this.radius));

        geo.computeVertexNormals();
        geo.computeBoundingBox();

        const mesh = new THREE.Mesh(geo, mat);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        return mesh;
    }

    private initCloud(): void {
        this.cloudGeo = new THREE.BufferGeometry();
        this.cloudMat = new THREE.MeshPhongMaterial({ color: 0xffffff, flatShading: true, shininess: 30, emissive: 0x222222 });
        const mesh = this.getMeshFromJson(this.cloudGeo, this.cloudMat, jsonLowGlobeCloud);

        this.cloudMeshGroup = new THREE.Group();

        for (let i = 0; i < 20; ++i) {
            const ms = mesh.clone();

            const long = 180 - Math.random() * 360;
            const lat = 90 - Math.random() * 180;
            const ele = this.radius + 1 + Math.random() * 0.1;
            const pos = this.toEarth(long, lat, ele)[1];
            ms.position.set(pos.x, pos.y, pos.z);

            ms.scale.setScalar(0.1 + (Math.random() - 0.5) * 0.1);
            ms.rotateY(Math.random() * Math.PI * 2);
            this.cloudMeshGroup.add(ms);
        }
        this.scene.add(this.cloudMeshGroup);
    }

    private initEnvironment(): void {
        this.envirMat = new THREE.MeshPhongMaterial({
            color: 0x50a993, shininess: 40, emissive: 0x9c9cbf,
            side: THREE.DoubleSide,
            opacity: 0.6,
            transparent: true,
            depthWrite: false,
        });

        this.envirGeometry = new THREE.SphereGeometry(100.01, this.xSeg, this.ySeg);
        this.envirMesh = new THREE.Mesh(this.envirGeometry, this.envirMat);

        this.scene.add(this.envirMesh);
    }

    public updatePost(): void {
        if (this.cloudMeshGroup) {
            this.cloudMeshGroup.rotation.y += 0.00035;
        }
    }

    private toEarth(long: number, lat: number, elevation: number):  any {
        return NVectorUtility.GetLineVecProjectedToGlobe(new NVector3(long, lat, this.radius), elevation);
    }

    public dispose(): void {
        this.cloudGeo.dispose();
        this.cloudMat.dispose();
        this.scene.remove(this.cloudMeshGroup);

        this.landMat.dispose();
        this.landGeometry.dispose();
        this.scene.remove(this.landMesh);

        this.sphereMat.dispose();
        this.sphereGeometry.dispose();
        this.scene.remove(this.sphereMesh);

        this.envirMat.dispose();
        this.envirGeometry.dispose();
        this.scene.remove(this.envirMesh);
    }
    UpdatePost(): void {
        throw new Error('Method not implemented.');
    }
    Dispose(): void {
        throw new Error('Method not implemented.');
    }
}